{"cell_index": 4, "code": "user_ids = rating_df["user_id"].unique().tolist()[:1000]
user2user_encoded = {x: i for i, x in enumerate(user_ids)}
user_encoded2user = {i: x for i, x in enumerate(user_ids)}
rating_df["user"] = rating_df["user_id"].map(user2user_encoded)
n_users = len(user2user_encoded)

anime_ids = rating_df["anime_id"].unique().tolist()[:1000]
anime2anime_encoded = {x: i for i, x in enumerate(anime_ids)}
anime_encoded2anime = {i: x for i, x in enumerate(anime_ids)}
rating_df["anime"] = rating_df["anime_id"].map(anime2anime_encoded)
n_animes = len(anime2anime_encoded)

# Filter to only include rows with valid user and anime encodings
rating_df = rating_df[rating_df['user'].notna() & rating_df['anime'].notna()].copy()
rating_df['user'] = rating_df['user'].astype(int)
rating_df['anime'] = rating_df['anime'].astype(int)

print("Num of users: {}, Num of animes: {}".format(n_users, n_animes))
print("Min rating: {}, Max rating: {}".format(min(rating_df['rating']), max(rating_df['rating'])))"}

